<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Lead extends Model { protected $fillable=['user_id','responsible_user_id','lead_list_id','prospecting_job_id','name','phone','email','website','instagram','linkedin','category','sector','estimated_revenue','employee_count','budget_value','tags','address','latitude','longitude','source','external_place_id','raw_data']; protected $casts=['raw_data'=>'array','tags'=>'array','estimated_revenue'=>'decimal:2','budget_value'=>'decimal:2']; public function user(){return $this->belongsTo(User::class);} public function responsible(){return $this->belongsTo(User::class,'responsible_user_id');} public function list(){return $this->belongsTo(LeadList::class,'lead_list_id');} public function job(){return $this->belongsTo(ProspectingJob::class,'prospecting_job_id');} public function notes(){return $this->hasMany(LeadNote::class)->latest();} public function activities(){return $this->hasMany(LeadActivity::class)->latest();} public function opportunity(){return $this->hasOne(PipelineOpportunity::class);} }
